export function DashboardWidget({
  title = "{{title}}",
  toolbar = {{toolbar}},
  size = "{{size}}",
  color = "{{color}}",
}) {
  const pad = { small: 8, medium: 14, large: 22 }[size] ?? 14;
  return (
    <section aria-labelledby="dwidget-react-title" style={{ border: "1px solid #24143018", borderLeft: `4px solid ${color}`, borderRadius: 10, background: "#FAF7F2", font: "13px system-ui, sans-serif", color: "#241430", padding: pad }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        <h3 id="dwidget-react-title" style={{ margin: 0, fontSize: 14 }}>{title}</h3>
        {toolbar && (
          <div style={{ display: "flex", gap: 4 }}>
            <button type="button" aria-label="Refresh" style={{ border: "1px solid #24143022", background: "#FAF7F2", borderRadius: 6, width: 24, height: 24, cursor: "pointer" }}>⟳</button>
            <button type="button" aria-label="More options" style={{ border: "1px solid #24143022", background: "#FAF7F2", borderRadius: 6, width: 24, height: 24, cursor: "pointer" }}>⋯</button>
          </div>
        )}
      </header>
      <div style={{ opacity: 0.7, minHeight: 40 }}>Widget content area</div>
    </section>
  );
}
